import json
import os
from pathlib import Path
from typing import Dict, List, Any

from .models import Book, Member, Loan

# internal representation
class LibraryDB:
    def __init__(self, path: str):
        self.path = Path(path)
        self.data: Dict[str, Any] = {
            "books": {},
            "members": {},
            "loans": {},  # isbn -> Loan
            "borrow_history": [],  # list of Loan
            "return_history": [],  # list of dict {loan, fee}
        }
        self._load()

    def _load(self):
        if self.path.exists():
            with self.path.open("r", encoding="utf-8") as f:
                raw = json.load(f)
                # books
                for isbn, rec in raw.get("books", {}).items():
                    self.data["books"][isbn] = Book(**rec)
                # members
                for mid, rec in raw.get("members", {}).items():
                    self.data["members"][mid] = Member(**rec)
                # loans
                for isbn, rec in raw.get("loans", {}).items():
                    self.data["loans"][isbn] = Loan(**rec)
                # histories
                self.data["borrow_history"] = [Loan(**rec) for rec in raw.get("borrow_history", [])]
                self.data["return_history"] = [
                    {"loan": Loan(**rec["loan"]), "fee": rec["fee"]}
                    for rec in raw.get("return_history", [])
                ]
        else:
            # ensure parent dir
            self.path.parent.mkdir(parents=True, exist_ok=True)

    def _save(self):
        serial = {
            "books": {isbn: vars(book) for isbn, book in self.data["books"].items()},
            "members": {mid: vars(member) for mid, member in self.data["members"].items()},
            "loans": {isbn: vars(loan) for isbn, loan in self.data["loans"].items()},
            "borrow_history": [vars(l) for l in self.data["borrow_history"]],
            "return_history": [
                {"loan": vars(r["loan"]), "fee": r["fee"]}
                for r in self.data["return_history"]
            ],
        }
        with self.path.open("w", encoding="utf-8") as f:
            json.dump(serial, f, indent=2)

    # CRUD helpers
    def add_book(self, book: Book):
        if book.isbn in self.data["books"]:
            raise ValueError("Book already exists")
        self.data["books"][book.isbn] = book
        self._save()

    def add_member(self, member: Member):
        if member.member_id in self.data["members"]:
            raise ValueError("Member already exists")
        self.data["members"][member.member_id] = member
        self._save()

    def get_book(self, isbn: str) -> Book:
        return self.data["books"].get(isbn)

    def get_member(self, member_id: str) -> Member:
        return self.data["members"].get(member_id)

    def add_loan(self, loan: Loan):
        if loan.isbn in self.data["loans"]:
            raise ValueError("Book already on loan")
        self.data["loans"][loan.isbn] = loan
        self.data["borrow_history"].append(loan)
        self._save()

    def remove_loan(self, isbn: str, fee: float):
        loan = self.data["loans"].pop(isbn, None)
        if loan is None:
            raise ValueError("No active loan for this ISBN")
        self.data["return_history"].append({"loan": loan, "fee": fee})
        self._save()
        return loan

    def list_loans(self) -> List[Loan]:
        return list(self.data["loans"].values())

    def list_borrow_history(self) -> List[Loan]:
        return list(self.data["borrow_history"])

    def list_return_history(self) -> List[Dict[str, Any]]:
        return list(self.data["return_history"])
