from datetime import date, timedelta
from typing import List

from .models import Loan

MAX_ACTIVE_LOANS = 3
LOAN_PERIOD_DAYS = 14
LATE_FEE_PER_DAY = 0.25
LATE_FEE_CAP = 10.00

# helper

def parse_date(d: str) -> date:
    return date.fromisoformat(d)

# rule checks

def check_borrow_limit(active_loans: List[Loan], member_id: str):
    count = sum(1 for l in active_loans if l.member_id == member_id)
    if count >= MAX_ACTIVE_LOANS:
        raise ValueError(f"Member {member_id} has reached the maximum of {MAX_ACTIVE_LOANS} active loans")

def compute_due_date(borrow_date: str) -> str:
    due = parse_date(borrow_date) + timedelta(days=LOAN_PERIOD_DAYS)
    return due.isoformat()

def compute_late_fee(due_date: str, return_date: str) -> float:
    due = parse_date(due_date)
    ret = parse_date(return_date)
    days_late = (ret - due).days
    if days_late <= 0:
        return 0.0
    fee = days_late * LATE_FEE_PER_DAY
    return min(fee, LATE_FEE_CAP)
