from collections import Counter
from typing import List, Dict

from .storage import LibraryDB

class LibraryReports:
    def __init__(self, db_path: str):
        self.db = LibraryDB(db_path)

    def overdue_isbns(self, as_of: str) -> List[str]:
        from datetime import date
        as_of_date = date.fromisoformat(as_of)
        overdue = []
        for loan in self.db.list_loans():
            due = date.fromisoformat(loan.due_date)
            if due < as_of_date:
                overdue.append(loan.isbn)
        return sorted(set(overdue))

    def total_fees_per_member(self) -> Dict[str, float]:
        totals: Dict[str, float] = {}
        for rec in self.db.list_return_history():
            member_id = rec["loan"].member_id
            totals[member_id] = totals.get(member_id, 0.0) + rec["fee"]
        return dict(sorted(totals.items()))

    def most_borrowed_isbns(self, top_n: int = 5) -> List[str]:
        from collections import Counter
        counter = Counter(l.isbn for l in self.db.list_borrow_history())
        return [isbn for isbn, _ in counter.most_common(top_n)]
